head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[date > M > isValidDate]<br/>yyyyMMdd 형식의 날짜값이 유효한 날짜인지 검증합니다.",
    "validation" : [
        "info(필수) 파라미터로 date 파라미터값이 유효하지 않을 때 포커스를 받을 WebSquare 컴포넌트 객체를 설정할 수 있어야 합니다.",
        "date(필수) 파라미터로 검증 대상 날짜를 yyyyMMdd 형식의 문자열로 설정할 수 있어야 합니다.",
        "options.useAlert(선택) 를 true 로 설정 시 유효하지 않은 날짜일 때 alert 메시지를 표시해야 합니다.",
        "options.useAlert(선택) 를 false 로 설정 시 alert 을 표시하지 않아야 합니다.",
        "options.useAlert(선택) 생략 시 기본값 true 로 동작하여 alert 메시지를 표시해야 합니다.",
        "options.returnType(선택) 을 'boolean' 으로 설정 시 유효하면 true, 유효하지 않으면 false 를 반환해야 합니다.",
        "options.returnType(선택) 을 'json' 으로 설정 시 유효하면 {result: true}, 유효하지 않으면 {result: false, message: 메시지} 를 반환해야 합니다.",
        "options.returnType(선택) 생략 시 기본값 'boolean' 으로 동작해야 합니다.",
        "유효하지 않은 날짜일 때 info 파라미터의 컴포넌트에 focus() 와 select() 를 호출해야 합니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // inputCalendar 컴포넌트 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof inputCalendar1 !== 'undefined') {
        inputCalendar1.remove();
    }

    $c.gcm.createLabel('label="info=inputCalendar1 설정"', '', 'label1');

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar('', 'ev:onfocus="scwin.inputCalendar1_onfocus"', 'inputCalendar1');
}



scwin.btn_isValidDate_onclick = function () {
    let date = par_date.getValue();
    let useAlert = par_useAlert.getValue();
    let returnType = par_returnType.getValue();

    let options = {};
    let omitOptions = true;

    if (useAlert !== 'omit') {
        options.useAlert = useAlert;
        omitOptions = false;
    }
    if (returnType !== 'omit') {
        options.returnType = returnType;
        omitOptions = false;
    }

    let ret;
    if (omitOptions) {
        ret = WebSquare.date.isValidDate(inputCalendar1, date);
        wf_body_bottom.getObj("scwin").setReturnValue("isValidDate(inputCalendar1, '" + date + "') : " + ret);
    } else {
        ret = WebSquare.date.isValidDate(inputCalendar1, date, options);
        if (returnType === 'json') {
            wf_body_bottom.getObj("scwin").setReturnValue("isValidDate(inputCalendar1, '" + date + "', options) : " + JSON.stringify(ret));
        } else {
            wf_body_bottom.getObj("scwin").setReturnValue("isValidDate(inputCalendar1, '" + date + "', options) : " + ret);
        }
    }
}



scwin.btn_getFocusOnDateSelect_onclick = function (e) {
    // id가 "target1"을 포함하는 요소를 찾기
    let targetEmement = document.querySelector('[id*="inputCalendar1"]');

    if (targetEmement) {
        let inputElement = null;

        // id가 "target1_input"을 포함하는 input 태그 찾기
        inputElement = targetEmement.querySelector('input[id*="inputCalendar1_input"]');

        wf_body_bottom.getObj("scwin").setReturnValue('selectionStart :' + inputElement.selectionStart);       
        wf_body_bottom.getObj("scwin").setReturnValue('selectionEnd :' + inputElement.selectionEnd);       
    }
}



scwin.inputCalendar1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====inputCalendar1_onfocus=====");

    setTimeout(() => {
        scwin.btn_getFocusOnDateSelect_onclick();
    },100);
}
